-- 2) Preise übernehmen (gleicher Ort und Betreiber, nur neue Nummer im Register)
INSERT INTO station_preise (station_id,preis_text,hinweis,link,sicherheit,recherchiert) SELECT '1128213',preis_text,hinweis,link,sicherheit,recherchiert FROM station_preise WHERE station_id='1036683' ON CONFLICT (station_id) DO NOTHING;
INSERT INTO station_preise (station_id,preis_text,hinweis,link,sicherheit,recherchiert) SELECT '1154158',preis_text,hinweis,link,sicherheit,recherchiert FROM station_preise WHERE station_id='1155112' ON CONFLICT (station_id) DO NOTHING;

-- 3) im Register nicht mehr vorhandene Stationen löschen (löscht deren Preiszeile mit)
DELETE FROM stationen WHERE id IN ('1035940','1036683','1055235','1155112');

-- 4) Zähler je Betreiber neu berechnen
UPDATE betreiber b SET standorte = (SELECT count(*) FROM stationen s WHERE b.name = ANY(s.betreiber));

COMMIT;
